   "notes": "Zhao(1) Zhen(3) [9004] Zhenzong's [9003] sixth son, Yingzong's [9005] distant cousin. His maternal grandfather was Li(2) Rende [7277]. Qian(1) Jingzhen's [7141] father-in-law, Qian(1) Chen's [7140] maternal grandfather. His consort was Zhang(1) Yaozuo's [321] niece. His empress Guo(1) [4216] was the sister of the father-in-law of Li(2) Chongju's [984] great grandson, Duanyi [3543]. Empress Guo(1) is alleged to have caused Lu(9) Yijian's [8100] dismissal after Renzong took over personal control of the government and Renzong and Lu(9) Yijian planned to remove artisans of the former regent Yang(2) Huangtaihou [4215]: Zhang(1) Qi(2) [8009], Fan(2) Yong [593], Yan(5) Shu [2073], Qian(1) Weiyan [8006], Xia(2) Song [703], Chen(1) Yaozuo [98], and Zhao(1) Sheng's [2073] son, Ji [3194], from their positions of power. It is also alleged that the adopted eunuch son of Yan(4) Chenghan [2067] (qv.), Yan(4) Wenying [4117], had a hand in the subsequent sudden death of empress Guo(1). Cao(1) Bin's [8134] fifth son, Qi [3869], was the father of Renzong's third empress, the Cisheng guangxian hou [4220]. Cao(1) Cong's [7357] grandson, Shi [3878], married Renzong's eleventh daughter. Zhang Fangping, WJ, 38.1a-3b; CBD, 2, 1688 (consort [fei], born Yu, died in 1064 at age 44); CBD, 3, 2212 (Empress Cao, who died in 1079 at age 64). CBD, 1, 762.",
